-- inspection.db → PostgreSQL schema (Chunk 3 of the PG migration).
-- Mirrors inspection-db.js _initSchema with the canonical type-preservation
-- recipe used by the tracker + meetings chunks:
--   AUTOINCREMENT            -> GENERATED BY DEFAULT AS IDENTITY
--   created_at/updated_at    -> TIMESTAMPTZ now()  (DB-managed timestamps)
--   submitted_at/signed_at   -> TIMESTAMPTZ now()  (DB-stamped)
--   app-supplied date/text   -> TEXT (inspection_date, due_date, closed_at, …)
--   active / display_order   -> INTEGER (boolean-ish kept numeric)
--   FK ON DELETE CASCADE     -> preserved
--   data_b64 / file_ref      -> TEXT (blobs live on the filesystem via blobStore;
--                               these columns are dual-read fallbacks)
-- Idempotent: IF NOT EXISTS throughout so initPgInspection can re-run at boot.

CREATE TABLE IF NOT EXISTS insp_sites (
  code           TEXT PRIMARY KEY,
  name_en        TEXT NOT NULL,
  name_fr        TEXT,
  country        TEXT,
  site_type      TEXT DEFAULT 'mine',
  display_order  INTEGER DEFAULT 0,
  active         INTEGER DEFAULT 1
);

CREATE TABLE IF NOT EXISTS insp_areas (
  code           TEXT PRIMARY KEY,
  name_en        TEXT NOT NULL,
  name_fr        TEXT,
  area_group     TEXT,
  display_order  INTEGER DEFAULT 0,
  active         INTEGER DEFAULT 1
);

CREATE TABLE IF NOT EXISTS insp_types (
  code           TEXT PRIMARY KEY,
  label_en       TEXT NOT NULL,
  label_fr       TEXT,
  display_order  INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS insp_inspections (
  id                   TEXT PRIMARY KEY,
  label                TEXT,
  inspection_date      TEXT,
  inspection_time      TEXT,
  inspection_type      TEXT,
  site_code            TEXT,
  area_code            TEXT,
  area_text            TEXT,
  specific_location    TEXT,
  inspector_name       TEXT,
  inspector_role       TEXT,
  accompanied_by       TEXT,
  weather              TEXT,
  last_inspection_date TEXT,
  scope                TEXT,
  overall_risk         TEXT,
  operational_impact   TEXT,
  key_observations     TEXT,
  positive_findings    TEXT,
  distribution         TEXT,
  state_json           TEXT,
  status               TEXT DEFAULT 'draft',
  created_by           INTEGER,
  created_at           TIMESTAMPTZ DEFAULT now(),
  updated_at           TIMESTAMPTZ DEFAULT now(),
  submitted_at         TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_insp_site_date ON insp_inspections(site_code, inspection_date);
CREATE INDEX IF NOT EXISTS ix_insp_status    ON insp_inspections(status);

CREATE TABLE IF NOT EXISTS insp_findings (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  inspection_id   TEXT NOT NULL REFERENCES insp_inspections(id) ON DELETE CASCADE,
  category        TEXT NOT NULL,
  item_index      INTEGER NOT NULL,
  item_code       TEXT,
  item_text_en    TEXT,
  item_text_fr    TEXT,
  status          TEXT,
  notes           TEXT,
  UNIQUE(inspection_id, category, item_index)
);
CREATE INDEX IF NOT EXISTS ix_insp_findings_status ON insp_findings(status);

CREATE TABLE IF NOT EXISTS insp_actions (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  inspection_id   TEXT NOT NULL REFERENCES insp_inspections(id) ON DELETE CASCADE,
  ord             INTEGER NOT NULL DEFAULT 0,
  description     TEXT,
  linked_item     TEXT,
  priority        TEXT,
  owner           TEXT,
  due_date        TEXT,
  status          TEXT DEFAULT 'Open',
  notes           TEXT,
  created_at      TIMESTAMPTZ DEFAULT now(),
  updated_at      TIMESTAMPTZ DEFAULT now(),
  closed_at       TEXT
);
CREATE INDEX IF NOT EXISTS ix_insp_actions_inspection ON insp_actions(inspection_id);

CREATE TABLE IF NOT EXISTS insp_action_updates (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  action_id     BIGINT NOT NULL REFERENCES insp_actions(id) ON DELETE CASCADE,
  author_id     INTEGER,
  author_name   TEXT,
  body          TEXT,
  status_change TEXT,
  created_at    TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_insp_action_updates_action ON insp_action_updates(action_id);

CREATE TABLE IF NOT EXISTS insp_photos (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  inspection_id   TEXT NOT NULL REFERENCES insp_inspections(id) ON DELETE CASCADE,
  finding_key     TEXT,
  action_id       BIGINT,
  caption         TEXT,
  mime_type       TEXT DEFAULT 'image/jpeg',
  data_b64        TEXT,
  file_ref        TEXT,
  size_bytes      INTEGER,
  created_at      TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_insp_photos_inspection ON insp_photos(inspection_id);

CREATE TABLE IF NOT EXISTS insp_signatures (
  inspection_id   TEXT NOT NULL REFERENCES insp_inspections(id) ON DELETE CASCADE,
  signer_type     TEXT NOT NULL,
  signer_name     TEXT,
  signer_date     TEXT,
  signature_b64   TEXT,
  file_ref        TEXT,
  signed_at       TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (inspection_id, signer_type)
);

CREATE TABLE IF NOT EXISTS insp_categories (
  code          TEXT PRIMARY KEY,
  name_en       TEXT NOT NULL,
  name_fr       TEXT,
  icon          TEXT,
  display_order INTEGER DEFAULT 0,
  active        INTEGER DEFAULT 1,
  created_at    TIMESTAMPTZ DEFAULT now()
);
